#!/usr/bin/env python3
import base64,sys,os
D=os.path.dirname(os.path.abspath(__file__)); IDX=os.path.join(D,'index.html')
JS=base64.b64decode("").decode()
NEW_UI=base64.b64decode("").decode()
NEW_ADD=base64.b64decode("").decode()
h=open(IDX,encoding='utf-8').read()
if 'AI_PROVIDERS' in h:
    print('ABORT: already has provider picker'); sys.exit(2)
# Op1: replace beHtml input block
iname=h.find('id="nbName"')
if iname<0: raise SystemExit('nbName not found')
istart=h.rfind('<div class="row" style="margin-top:8px">',0,iname)
end='+ Link model</button></div>'
iend=h.find(end,iname)
if istart<0 or iend<0: raise SystemExit('beHtml anchors missing')
iend+=len(end)
h=h[:istart]+NEW_UI+h[iend:]
# Op2: replace addBackend
a0=h.find('async function addBackend(){')
if a0<0: raise SystemExit('addBackend not found')
a1=h.find('toast("Model linked");',a0)
a1e=h.find('\n}',a1)+2
h=h[:a0]+NEW_ADD+h[a1e:]
# Op3: init hook
anc='sb=supabase.createClient(CONFIG.SUPABASE_URL,CONFIG.SUPABASE_ANON_KEY);'
i=h.find(anc)
if i<0: raise SystemExit('createClient not found')
h=h[:i+len(anc)]+'\n  handleOAuthReturn();'+h[i+len(anc):]
# Op4: append JS before last </script>
sc=h.rfind('</script>')
h=h[:sc]+JS+'\n'+h[sc:]
open(IDX,'w',encoding='utf-8',newline='\r\n').write(h)
print('OK provider picker; AI_PROVIDERS=',h.count('AI_PROVIDERS'),'onProviderPick=',h.count('onProviderPick'),'addBackend=',h.count('function addBackend'),'handleOAuthReturn=',h.count('handleOAuthReturn'))
